import React, { useState, useEffect } from "react";

function Home() {
  const [resumeText, setResumeText] = useState("");
  const [jobDesc, setJobDesc] = useState("");
  const [loading, setLoading] = useState(false);
  const [result, setResult] = useState(null);
  const [template, setTemplate] = useState("simple");
  const [matchData, setMatchData] = useState(null);
  const [photo, setPhoto] = useState(null);

  // ================= AUTH =================
  useEffect(() => {
    const token = localStorage.getItem("token");
    if (!token) window.location.href = "/login";
  }, []);

  // ================= OPTIMIZE =================
  const handleOptimize = async () => {
    if (!resumeText.trim() || !jobDesc.trim()) {
      return alert("Provide Resume + Job Description");
    }

    setLoading(true);

    try {
      const token = localStorage.getItem("token");

      const res = await fetch("http://localhost:5000/api/resume/optimize", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${token}`,
        },
        body: JSON.stringify({
          resumeText,
          jobDesc,
          template,
          photo,
        }),
      });

      const data = await res.json();

      if (!res.ok) {
        alert(data.msg || "Optimization failed");
        return;
      }

      setResult(data);

    } catch (err) {
      console.log(err);
      alert("Server error");
    } finally {
      setLoading(false);
    }
  };

  // ================= SAVE =================
  const handleSave = async () => {
    try {
      const token = localStorage.getItem("token");

      if (!result?.optimizedText) {
        return alert("Optimize first");
      }

      const res = await fetch("http://localhost:5000/api/resume/save", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${token}`,
        },
        body: JSON.stringify({
          text: result.optimizedText,
          atsScore: result.score,
        }),
      });

      const data = await res.json();

      if (!res.ok) {
        alert(data.msg || "Save failed");
        return;
      }

      alert("Saved successfully");

    } catch (err) {
      console.log(err);
      alert("Save failed");
    }
  };

  // ================= MATCH =================
  const handleMatch = async () => {
    try {
      const token = localStorage.getItem("token");

      if (!resumeText.trim() || !jobDesc.trim()) {
        return alert("Provide resume + job description");
      }

      const res = await fetch("http://localhost:5000/api/resume/match", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${token}`,
        },
        body: JSON.stringify({ resumeText, jobDesc }),
      });

      const data = await res.json();

      if (!res.ok) {
        alert(data.msg || "Match failed");
        return;
      }

      setMatchData(data);

    } catch (err) {
      console.log(err);
      alert("Match failed");
    }
  };

  // ================= RESUME UPLOAD =================
  const handleResumeUpload = async (e) => {
    const file = e.target.files[0];
    const token = localStorage.getItem("token");

    if (!file) return;

    const formData = new FormData();
    formData.append("file", file);

    try {
      const res = await fetch("http://localhost:5000/api/resume/upload-pdf", {
        method: "POST",
        headers: {
          Authorization: `Bearer ${token}`,
        },
        body: formData,
      });

      const data = await res.json();

      if (!res.ok) {
        alert(data.msg || "Resume parsing failed");
        return;
      }

      // 🔥 IMPORTANT FIX
      setResumeText(data.text || "");

      console.log("✅ Resume loaded");

    } catch (err) {
      console.log(err);
      alert("Upload failed");
    }
  };

  // ================= JD UPLOAD =================
  const handleJDUpload = async (e) => {
    const file = e.target.files[0];
    const token = localStorage.getItem("token");

    if (!file) return;

    const formData = new FormData();
    formData.append("file", file);

    try {
      const res = await fetch("http://localhost:5000/api/resume/upload-pdf", {
        method: "POST",
        headers: {
          Authorization: `Bearer ${token}`,
        },
        body: formData,
      });

      const data = await res.json();

      if (!res.ok) {
        alert(data.msg || "JD parsing failed");
        return;
      }

      // 🔥 IMPORTANT FIX
      setJobDesc(data.text || "");

      console.log("✅ JD loaded");

    } catch (err) {
      console.log(err);
      alert("Upload failed");
    }
  };

  // ================= PHOTO =================
  const handlePhoto = (e) => {
    const reader = new FileReader();
    reader.onloadend = () => {
      setPhoto(reader.result.split(",")[1]);
    };
    reader.readAsDataURL(e.target.files[0]);
  };

  // ================= DOWNLOAD =================
  const handleDownload = async () => {
    try {
      const token = localStorage.getItem("token");

      const res = await fetch("http://localhost:5000/api/resume/download", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${token}`,
        },
        body: JSON.stringify({
          text: result.optimizedText,
          template,
          photo,
        }),
      });

      const blob = await res.blob();
      const url = window.URL.createObjectURL(blob);

      const a = document.createElement("a");
      a.href = url;
      a.download = "resume.pdf";
      a.click();

    } catch (err) {
      console.log(err);
      alert("Download failed");
    }
  };

  return (
    <div style={styles.page}>
      <h1 style={styles.logo}>CareerForge Pro 🚀</h1>

      <div style={styles.card}>
        <h3 style={styles.heading}>📄 Resume</h3>
        <input type="file" accept=".pdf" onChange={handleResumeUpload} />

        <textarea
          placeholder="Paste Resume..."
          value={resumeText}
          onChange={(e) => setResumeText(e.target.value)}
          style={styles.textarea}
        />

        <h3 style={styles.heading}>💼 Job Description</h3>
        <input type="file" accept=".pdf" onChange={handleJDUpload} />

        <textarea
          placeholder="Paste Job Description..."
          value={jobDesc}
          onChange={(e) => setJobDesc(e.target.value)}
          style={styles.textarea}
        />

        <h3 style={styles.heading}>🖼 Upload Photo</h3>
        <input type="file" onChange={handlePhoto} />

        <select
          value={template}
          onChange={(e) => setTemplate(e.target.value)}
          style={styles.select}
        >
          <option value="simple">Simple</option>
          <option value="modern">Modern</option>
          <option value="professional">Professional</option>
          <option value="minimal">Minimal</option>
        </select>

        <button style={styles.primaryBtn} onClick={handleOptimize}>
          {loading ? "Optimizing..." : "Optimize Resume"}
        </button>

        <button style={styles.secondaryBtn} onClick={handleMatch}>
          Check Job Match
        </button>
      </div>

      {result && (
        <div style={styles.resultCard}>
          <h2>ATS Score: {result.score}</h2>

          <pre style={styles.output}>{result.optimizedText}</pre>

          <button style={styles.primaryBtn} onClick={handleSave}>
            Save Resume
          </button>

          <button style={styles.primaryBtn} onClick={handleDownload}>
            Download PDF
          </button>
        </div>
      )}

      {matchData && (
        <div style={styles.resultCard}>
          <h2>Job Match</h2>
          <p>Score: {matchData.matchScore}</p>
          <p>{matchData.message}</p>
        </div>
      )}
    </div>
  );
}

// ================= STYLES =================
const styles = {
  page: {
    minHeight: "100vh",
    background: "#020617",
    padding: "30px",
    color: "white",
    textAlign: "center",
  },
  logo: { color: "#38bdf8" },
  card: {
    background: "#0f172a",
    padding: "20px",
    borderRadius: "16px",
    width: "70%",
    margin: "auto",
    display: "flex",
    flexDirection: "column",
    gap: "12px",
  },
  heading: { textAlign: "left", color: "#94a3b8" },
  textarea: {
    height: "120px",
    background: "#020617",
    color: "white",
    border: "1px solid #334155",
    padding: "10px",
    borderRadius: "8px",
  },
  select: {
    padding: "10px",
    borderRadius: "8px",
    background: "#020617",
    color: "white",
  },
  primaryBtn: {
    background: "#3b82f6",
    padding: "10px",
    border: "none",
    borderRadius: "8px",
    color: "white",
    cursor: "pointer",
  },
  secondaryBtn: {
    background: "#9333ea",
    padding: "10px",
    border: "none",
    borderRadius: "8px",
    color: "white",
    cursor: "pointer",
  },
  resultCard: {
    marginTop: "20px",
    padding: "20px",
    background: "#0f172a",
    borderRadius: "12px",
    width: "70%",
    margin: "auto",
  },
  output: {
    background: "#020617",
    padding: "10px",
    borderRadius: "8px",
    textAlign: "left",
    whiteSpace: "pre-wrap",
  },
};

export default Home;
